@push('scripts')<script>$(function(){const t=$('#issue-table'),e=$.fn.dataTable.render.text(),f=$('#issue-filters');const table=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{processing:true,serverSide:true,ajax:{url:'{{ $productionMode ? route('wms.production.material-issues.data') : route('wms.issues.data') }}',data:function(d){d.status=f.find('.js-wms-filter-status').val();d.issue_type=f.find('.js-wms-filter-issue-type').val();d.date_from=f.find('.js-wms-filter-from').val();d.date_to=f.find('.js-wms-filter-to').val();}},buttons:[window.erpExcelButton(t)],columns:[{data:'document_number',render:e.display},{data:'business_date',render:e.display}@unless($productionMode),{data:'issue_type_label',render:e.display}@endunless,{data:'line_count',render:(v,x)=>x==='display'?e.display(v+' รายการ'):v},{data:'quantity',className:'text-end',render:e.display}@if($productionMode),{data:'finished_receipt_label',render:e.display}@else,{data:'return_document_label',render:e.display}@endif,{data:'reason',render:e.display},{data:'status_label',render:(v,x,r)=>x==='display'?'<span class="badge '+(r.status==='POSTED'?'app-status-success':r.status==='APPROVED'?'app-status-info':'app-status-neutral')+'">'+e.display(v)+'</span>':v},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:(v,x,r)=>{if(x!=='display')return '';let h='<a class="btn btn-sm btn-app-soft" href="'+r.show_url+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-show"></i></a> ';if(r.can_approve)h+='<button class="btn btn-sm btn-app-soft js-issue" data-id="'+r.id+'" data-action="approve" title="อนุมัติ"><i class="bx bx-check"></i></button> ';if(r.can_post)h+='<button class="btn btn-sm btn-app-soft js-issue" data-id="'+r.id+'" data-action="post" title="ลง Stock"><i class="bx bx-send"></i></button> ';if(r.can_delete)h+='<button class="btn btn-sm btn-app-danger js-issue" data-id="'+r.id+'" data-action="delete" title="ลบร่าง"><i class="bx bx-trash"></i></button>';return h;}}]}));f.on('click','.js-wms-apply-filter',function(){table.ajax.reload();});f.on('click','.js-wms-reset-filter',function(){f.find('select,input').val('');table.ajax.reload();});$(document).on('click','.js-issue',function(){const b=$(this),a=b.data('action');Swal.fire({icon:'warning',title:a==='approve'?'อนุมัติใบเบิก?':a==='post'?'ลง Stock?':'ลบร่าง?',showCancelButton:true,confirmButtonText:'ยืนยัน',cancelButtonText:'ยกเลิก'}).then(x=>{if(!x.isConfirmed)return;$.ajax({url:'{{ url('/wms/issues') }}/'+b.data('id')+'/'+a,type:a==='delete'?'DELETE':'POST',data:{_token:$('meta[name=csrf-token]').attr('content')}}).done(r=>{Swal.fire({icon:'success',text:r.msg,timer:1000,showConfirmButton:false});table.ajax.reload(null,false)}).fail(x=>Swal.fire({icon:'error',text:x.responseJSON?.message||'ดำเนินการไม่สำเร็จ'}));});});});</script>@endpush
